/bin/zsh -lc "python3 -c 'from pathlib import Path; import re; s=Path(\"material.md\").read_text(); blocks=re.findall(r\""'```text'"\\n(.*?)\\n"'```",s,re.S); a=list(map(int,blocks[0].split())); n=a[0]; expected=a[1:]; out=blocks[1].split(); assert out[0]=="YES"; v=list(map(int,out[1:])); assert len(v)==2*(n-1); adj=[[] for _ in range(n)]; degree=[0]*n; edges=set(); valid=True
for u,w in zip(v[::2],v[1::2]):
 valid=valid and 1<=u<=n and 1<=w<=n and u!=w and tuple(sorted((u,w))) not in edges
 edges.add(tuple(sorted((u,w)))); adj[u-1].append(w-1); adj[w-1].append(u-1); degree[u-1]+=1; degree[w-1]+=1
seen={0}; stack=[0]
while stack:
 u=stack.pop()
 for w in adj[u]:
  if w not in seen: seen.add(w); stack.append(w)
print({"sample_edges":len(edges),"simple":valid,"connected":len(seen)==n,"actual_degrees":degree,"expected_degrees":expected,"degree_match":degree==expected})'"'"

